Core Transactional Service Container.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Core Transactional Service Container container

Container_Boundary(core_transactional_service_container, "Core Transactional Service Container") {
    Component(circulation_and_cataloguing_module, "Circulation and Cataloguing Module", "Domain-Driven Design (DDD)", "Handles core business logic and modular monolith boundaries for circulation and cataloguing.")
    Component(transactional_outbox_processor, "Transactional Outbox Processor", "Transactional Outbox Pattern", "Ensures reliable event publishing without dual-write inconsistencies.")
    Component(concurrency_control_manager, "Concurrency Control Manager", "Optimistic Concurrency Control", "Handles high-contention item checkouts via version columns.")
}

Rel(circulation_and_cataloguing_module, transactional_outbox_processor, "Persists events for reliable publishing")
Rel(circulation_and_cataloguing_module, concurrency_control_manager, "Manages checkout consistency and versions")

@enduml

Message Broker Container.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Message Broker Container container

Container_Boundary(message_broker_container, "Message Broker Container") {
    Component(Event_Publisher_Receiver, "Event Publisher Receiver", "RabbitMQ / Kafka", "Receives and decouples write operations from the Core Transactional Service.")
    Component(Event_Stream_Dispatcher, "Event Stream Dispatcher", "Asynchronous Message Stream", "Consumes and streams events to the Search Service Container for indexing.")
}

Rel(Event_Publisher_Receiver, Event_Stream_Dispatcher, "Routes and dispatches events for search indexing", "Asynchronous Message Stream")

@enduml

Distributed Cache Container.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Person(Core Transactional Service Container, "Core Transactional Service Container", "External client container")
System_Ext(Enterprise Logging and Monitoring Service, "Enterprise Logging and Monitoring Service", "External monitoring system")

Container_Boundary(Distributed Cache, "Distributed Cache Container") {
    Component(Redis Cache Engine, "Redis Cache Engine", "Redis, AOF/RDB Persistence, Redis Protocol with TLS", "High-throughput, low-latency caching engine providing sub-800ms search performance and EU data residency compliance.")
    Component(Cache Management and Resilience Module, "Cache Management and Resilience Module", "Resilience4j / Polly, Protocol Buffers / Compressed JSON", "Handles connection pooling, circuit breaking, cache stampede prevention, and efficient payload serialization.")
    Component(Telemetry and Testing Adapter, "Telemetry and Testing Adapter", "Testcontainers", "Exports telemetry and metrics to the monitoring service and supports automated integration testing of caching logic.")
}

Rel(Core Transactional Service Container, Redis Cache Engine, "Caches and retrieves fast data", "Redis Protocol with TLS")
Rel(Redis Cache Engine, Enterprise Logging and Monitoring Service, "Exports telemetry and metrics", "")

@enduml

Observability Sidecars.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Observability Sidecars container

Container_Boundary(observability_sidecars, "Observability Sidecars") {
    Component(OpenTelemetry_Collector_Agent, "OpenTelemetry Collector Agent", "OpenTelemetry Collector", "Acts as a standard sidecar pattern for local telemetry buffering, scrubbing, and dynamic pipeline reloading.")
    Component(Prometheus_Endpoint, "Prometheus Endpoint", "Prometheus", "Exposes Prometheus-compatible endpoints for internal metrics monitoring such as drop counters, queue depth, and export latency.")
    Component(Spooling_Buffer_Manager, "Spooling Buffer Manager", "Bounded local disk storage", "Handles backpressure management and data spooling during downstream outages.")
}

Rel(OpenTelemetry_Collector_Agent, Spooling_Buffer_Manager, "Routes invalid or unprocessable payloads to secure local storage via a dead-letter queue (DLQ) strategy", "DLQ")
Rel(Prometheus_Endpoint, OpenTelemetry_Collector_Agent, "Monitors internal metrics and operational health", "HTTP")

@enduml
